-- Completes each half-saved order the way HQ's final save would: header totals from the lines, the firm's charge layout
-- (copied from the latest finished order of the same type, all amounts 0 - orders never round), the zero VAT summary.
-- Orders without any line are left for TX02 owner review (none today).
DECLARE @doc int, @tt int, @net numeric(18,2);
DECLARE c CURSOR LOCAL FAST_FORWARD FOR
  SELECT h.Doc_Id, h.Tt_Id, (SELECT SUM(o.NetValue) FROM dbo.IQOrd_Detail o WHERE o.Doc_ID=h.Doc_Id)
  FROM dbo.IQDoc_Header h
  WHERE h.Tt_Id IN (248,249) AND NOT EXISTS (SELECT 1 FROM dbo.IQDOC_VAT v WHERE v.Doc_Id=h.Doc_Id)
    AND EXISTS (SELECT 1 FROM dbo.IQOrd_Detail o WHERE o.Doc_ID=h.Doc_Id);
OPEN c; FETCH NEXT FROM c INTO @doc, @tt, @net;
WHILE @@FETCH_STATUS = 0
BEGIN
  UPDATE dbo.IQDoc_Header SET Product_Value=@net, Bill_Amt=@net, Supp_BillAmt=@net WHERE Doc_Id=@doc;
  UPDATE dbo.IQOrd_Detail SET RecdOrDelv_ID=OrdDltdID WHERE Doc_ID=@doc AND ISNULL(RecdOrDelv_ID,0)=0;
  IF NOT EXISTS (SELECT 1 FROM dbo.IQDoc_Chrgs WHERE Doc_id=@doc)
  BEGIN
    DECLARE @ln int, @chrg int, @cidx tinyint, @act int, @calc numeric(18,4);
    DECLARE k CURSOR LOCAL FAST_FORWARD FOR
      SELECT t.Ln_No, t.Chrg_id, t.CIndx, t.Act_ID FROM dbo.IQDoc_Chrgs t
      WHERE t.Doc_id=(SELECT MAX(x.Doc_Id) FROM dbo.IQDoc_Header x WHERE x.Tt_Id=@tt AND EXISTS (SELECT 1 FROM dbo.IQDOC_VAT v WHERE v.Doc_Id=x.Doc_Id) AND EXISTS (SELECT 1 FROM dbo.IQDoc_Chrgs y WHERE y.Doc_id=x.Doc_Id));
    OPEN k; FETCH NEXT FROM k INTO @ln, @chrg, @cidx, @act;
    WHILE @@FETCH_STATUS = 0
    BEGIN
      SET @calc = CASE WHEN @ln=1 THEN 0 ELSE @net END;
      EXEC dbo.IQDoc_Chrgs_Insert @mDoc_id=@doc, @mLn_No=@ln, @mChrg_id=@chrg, @mCIndx=@cidx, @mRate=0, @mAmount=0, @mAct_ID=@act, @mChrg_Desc='', @mCalcOnAmt=@calc, @mTax5Amt=0, @mTax145Amt=0;
      FETCH NEXT FROM k INTO @ln, @chrg, @cidx, @act;
    END
    CLOSE k; DEALLOCATE k;
  END
  EXEC dbo.IQDOC_VAT_Insert @mDoc_Id=@doc, @mExempted=0, @mGross4=0, @mTax4=0, @mGross145=0, @mTax145=0, @mGross1=0, @mTax1=0, @mTaxSpec=0, @mCashDisc=0, @mFrieght=0, @mCrDr_Note=0, @mRndOff=0;
  FETCH NEXT FROM c INTO @doc, @tt, @net;
END
CLOSE c; DEALLOCATE c;

-- Renumber 1..n in display order (Ln_No, then line id), as HQ does when it re-saves the grid. Amounts untouched.
UPDATE x SET Ln_No=x.rn FROM (SELECT o.Ln_No, ROW_NUMBER() OVER (PARTITION BY o.Doc_ID ORDER BY o.Ln_No, o.OrdDltdID) rn FROM dbo.IQOrd_Detail o
  WHERE o.Doc_ID IN (SELECT Doc_ID FROM dbo.IQOrd_Detail GROUP BY Doc_ID, Ln_No HAVING COUNT(*)>1)) x WHERE x.Ln_No<>x.rn;
UPDATE x SET Ln_no=x.rn FROM (SELECT d.Ln_no, ROW_NUMBER() OVER (PARTITION BY d.Doc_Id ORDER BY d.Ln_no, d.Delv_Id) rn FROM dbo.IQDoc_Delv d JOIN dbo.IQDoc_Header h ON h.Doc_Id=d.Doc_Id
  WHERE h.Doc_Date>='20261001' AND d.Doc_Id IN (SELECT Doc_Id FROM dbo.IQDoc_Delv GROUP BY Doc_Id, Ln_no HAVING COUNT(*)>1)) x WHERE x.Ln_no<>x.rn;
UPDATE x SET Ln_no=x.rn FROM (SELECT r.Ln_no, ROW_NUMBER() OVER (PARTITION BY r.Doc_ID ORDER BY r.Ln_no, r.Recd_Id) rn FROM dbo.IQDoc_Recd r JOIN dbo.IQDoc_Header h ON h.Doc_Id=r.Doc_ID
  WHERE h.Tt_Id<>222 AND h.Doc_Date>='20261001' AND r.Doc_ID IN (SELECT Doc_ID FROM dbo.IQDoc_Recd GROUP BY Doc_ID, Ln_no HAVING COUNT(*)>1)) x WHERE x.Ln_no<>x.rn;

UPDATE x SET Ln_no=x.rn FROM (SELECT d.Ln_no, ROW_NUMBER() OVER (PARTITION BY d.Doc_Id ORDER BY d.Ln_no, d.Delv_Id) rn FROM dbo.IQDoc_Delv d JOIN dbo.IQDoc_Header h ON h.Doc_Id=d.Doc_Id
  WHERE h.Doc_Date<'20261001' AND d.Doc_Id IN (SELECT Doc_Id FROM dbo.IQDoc_Delv GROUP BY Doc_Id, Ln_no HAVING COUNT(*)>1)) x WHERE x.Ln_no<>x.rn;
UPDATE x SET Ln_no=x.rn FROM (SELECT r.Ln_no, ROW_NUMBER() OVER (PARTITION BY r.Doc_ID ORDER BY r.Ln_no, r.Recd_Id) rn FROM dbo.IQDoc_Recd r JOIN dbo.IQDoc_Header h ON h.Doc_Id=r.Doc_ID
  WHERE h.Tt_Id<>222 AND h.Doc_Date<'20261001' AND r.Doc_ID IN (SELECT Doc_ID FROM dbo.IQDoc_Recd GROUP BY Doc_ID, Ln_no HAVING COUNT(*)>1)) x WHERE x.Ln_no<>x.rn;

-- Exactly HQ's menu "Update ClosingStock to Items List" (Mainfrm -> mdlGeneral.UpdateStock(0, cn, AllItemsUpdate:=True)).
UPDATE dbo.IQItems_Mast SET Stk=0;
EXEC dbo.[UpdateClosing_Stock_B+NG] @mItem_ID=0;

-- Only on the owner's yes: zero the impossible negative opening quantities, then refresh stock exactly as HQ's menu does.
UPDATE r SET Qty=0, Value=0, GrossValue=0, NetValue=0 FROM dbo.IQDoc_Recd r JOIN dbo.IQDoc_Header h ON h.Doc_Id=r.Doc_ID WHERE h.Tt_Id=222 AND r.Qty<0;
UPDATE h SET Bill_Amt=(SELECT SUM(x.NetValue) FROM dbo.IQDoc_Recd x WHERE x.Doc_ID=h.Doc_Id) FROM dbo.IQDoc_Header h WHERE h.Tt_Id=222;
UPDATE dbo.IQItems_Mast SET Stk=0;
EXEC dbo.[UpdateClosing_Stock_B+NG] @mItem_ID=0;

DELETE FROM dbo.IQDinamination WHERE CreditCardDtldID IN (SELECT x.CreditCardDtldID FROM dbo.IQCreditCard x WHERE x.Doc_id >= (SELECT MIN(h.Doc_Id) FROM dbo.IQDoc_Header h) AND NOT EXISTS (SELECT 1 FROM dbo.IQDoc_Header h WHERE h.Doc_Id=x.Doc_id) AND ISNULL(x.cash,0)+ISNULL(x.credit,0)+ISNULL(x.cheque,0)+ISNULL(x.card,0)+ISNULL(x.PhonePay,0)+ISNULL(x.GooglePay,0)+ISNULL(x.PayTM,0)+ISNULL(x.Others1,0)=0);
DELETE x FROM dbo.IQCreditCard x WHERE x.Doc_id >= (SELECT MIN(h.Doc_Id) FROM dbo.IQDoc_Header h) AND NOT EXISTS (SELECT 1 FROM dbo.IQDoc_Header h WHERE h.Doc_Id=x.Doc_id)
  AND ISNULL(x.cash,0)+ISNULL(x.credit,0)+ISNULL(x.cheque,0)+ISNULL(x.card,0)+ISNULL(x.PhonePay,0)+ISNULL(x.GooglePay,0)+ISNULL(x.PayTM,0)+ISNULL(x.Others1,0)=0;

-- Same order as HQ's Outward_Delete; only rows whose Doc_Id has no header. Refresh stock afterwards (TX07 fix).
DELETE x FROM dbo.IQDoc_Recd x WHERE NOT EXISTS (SELECT 1 FROM dbo.IQDoc_Header h WHERE h.Doc_Id=x.Doc_ID);
DELETE x FROM dbo.IQDoc_Delv x WHERE NOT EXISTS (SELECT 1 FROM dbo.IQDoc_Header h WHERE h.Doc_Id=x.Doc_Id);
DELETE x FROM dbo.IQOrd_Detail x WHERE NOT EXISTS (SELECT 1 FROM dbo.IQDoc_Header h WHERE h.Doc_Id=x.Doc_ID);
DELETE x FROM dbo.IQDOC_VAT x WHERE NOT EXISTS (SELECT 1 FROM dbo.IQDoc_Header h WHERE h.Doc_Id=x.Doc_Id);
DELETE x FROM dbo.IQDoc_Chrgs x WHERE NOT EXISTS (SELECT 1 FROM dbo.IQDoc_Header h WHERE h.Doc_Id=x.Doc_id);
DELETE x FROM dbo.IQCash_TRAN x WHERE NOT EXISTS (SELECT 1 FROM dbo.IQDoc_Header h WHERE h.Doc_Id=x.Doc_Id);
DELETE x FROM dbo.IQDayBook x WHERE x.Doc_ID>0 AND NOT EXISTS (SELECT 1 FROM dbo.IQDoc_Header h WHERE h.Doc_Id=x.Doc_ID)
  AND NOT EXISTS (SELECT 1 FROM dbo.ADJUST a WHERE x.SR_NO IN (a.Sr_No, a.Rel_Sr_No));
UPDATE dbo.IQItems_Mast SET Stk=0;
EXEC dbo.[UpdateClosing_Stock_B+NG] @mItem_ID=0;
